/// <reference types="react" />
export interface Props {
    id: number | string;
    paletteMode: string;
    color: string;
    isEmptyColor?: boolean;
    isEditMode?: boolean;
    onClick: (id: number | string, value: string) => void;
    onColorSwatchContextMenu?: ({ colorId, colorValue, event, isCurrentColorSwatch, }: {
        colorId: number | string;
        colorValue: string;
        event: React.MouseEvent;
        isCurrentColorSwatch?: boolean;
    }) => void;
    onEdit?: (id: number | string, color: string) => void;
    onDeleteGlobalColor?: (id: string) => void;
    tooltipId?: string;
    isGlobalColor?: boolean;
}
